import {buildingDetails} from './settlement-ui.js';
import * as G from './horizons.js';
const esc=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>Math.floor(n).toLocaleString('es-CO'),time=n=>n>=3600?(n/3600).toFixed(1)+' h':Math.ceil(n/60)+' min';
const head=(k,title,p)=>`<div class="panel-head"><div><div class="eyebrow">${k}</div><h2>${title}</h2></div><button data-action="close-panel" aria-label="Cerrar panel">×</button></div><p>${p}</p>`;
const art=(type,unit=false,tier=null,level=1)=>`<canvas data-art="${type}" data-level="${level}" ${tier===null?'':'data-tier="'+tier+'"'} ${unit?'data-unit="true"':''}></canvas>`;
const cost=(s,c)=>'<div class="cost">'+Object.entries(c).map(([k,v])=>`<span class="${G.currentMap(s).stock[k]<v?'missing':''}">${fmt(v)} ${G.STOCK_NAMES[k]}</span>`).join('')+'</div>';
const bar=(v,max=100)=>`<div class="progress"><i style="width:${Math.max(0,Math.min(100,v/max*100))}%"></i></div>`;
const taskNames={wood:'Leñador',stone:'Cantero',food:'Recolector de alimentos',water:'Aguador',farm:'Agricultor',well:'Operario de agua',mining:'Minero',industry:'Operario de instalación',idle:'Sin asignación'};
const benefit=(type,stats)=>type==='house'?'Población +'+stats.capacity:type==='reactor'||type==='fusion'?'Energía '+Math.round(stats.output*(type==='fusion'?40:10)):type==='cistern'?'Ahorro de agua '+Math.min(55,Math.round(stats.output*15))+'%':({school:'Investigación',tower:'Defensa',market:'Comercio',embassy:'Diplomacia',mine:'Excavación',hospital:'Curación',camp:'Reclutamiento',depot:'Logística'}[type]||'Producción')+' ×'+stats.output.toFixed(2);
function materialLedger(s,price){const m=G.currentMap(s);return '<div class="material-ledger"><p>Solo cuentan los materiales entregados en esta isla. La carga de los colonos todavía está en tránsito.</p><table><thead><tr><th>Material</th><th>Almacén</th><th>Necesitas</th><th>Falta</th></tr></thead><tbody>'+Object.entries(price).map(([k,n])=>'<tr><td><button data-action="material-help" data-type="'+k+'">'+G.STOCK_NAMES[k]+' ⓘ</button></td><td>'+fmt(m.stock[k])+'</td><td>'+fmt(n)+'</td><td class="'+(m.stock[k]<n?'missing':'')+'">'+fmt(Math.max(0,n-m.stock[k]))+'</td></tr>').join('')+'</tbody></table></div>';}
export function upgradeView(s,id){const m=G.currentMap(s),b=m.buildings.find(v=>v.id===id);if(!b)return'';const spec=G.STRUCTURES[b.type],q=G.upgradeQuote(s,m,b,spec),now=G.buildingStats(b,spec),next=G.buildingStats({...b,level:q.next,tier:s.era},spec),job=m.civicJobs.find(j=>j.building===id&&j.kind==='upgrade');return`<div class="panel-head"><div><div class="eyebrow">EDIFICIO · ${esc(G.ERAS[b.tier||0].name)}</div><h2>${spec.name}</h2></div><button data-action="close-modal" aria-label="Cerrar">×</button></div><div class="upgrade-art compare-models"><div>${art(b.type,false,b.tier,b.level)}<small>ACTUAL · NIVEL ${b.level}</small></div><span>→</span><div>${art(b.type,false,q.refit?s.era:b.tier,Math.min(10,q.next||b.level))}<small>${q.maxed?'MÁXIMO DE LA ERA':q.refit?'NUEVO PLANO':'SIGUIENTE · NIVEL '+Math.min(10,q.next||b.level)}</small></div></div><p>${spec.description}</p><div class="level-pips" aria-label="Nivel ${b.level} de 10">${Array.from({length:10},(_,i)=>`<i class="${i<b.level?'filled':''}">${i+1}</i>`).join('')}</div><div class="upgrade-comparison"><div><small>ACTUAL · NIVEL ${b.level}</small><strong>${fmt(now.hp)} integridad</strong><span>${benefit(b.type,now)}</span></div><b>→</b><div><small>${q.refit?'ADAPTAR A '+G.ERAS[s.era].name.toUpperCase():'NIVEL '+Math.min(10,q.next)}</small><strong>${fmt(next.hp)} integridad</strong><em class="upgrade-delta">+${fmt(next.hp-now.hp)} integridad</em><span>${benefit(b.type,next)}</span></div></div>${job?`<div class="card"><h3>Mejora en curso</h3>${bar(job.elapsed,job.duration)}<p>${time(job.duration-job.elapsed)} de trabajo restante. Necesita su constructor junto a la obra.</p><button data-action="resume-civic" data-id="${job.id}">Asignar constructor disponible</button></div>`:q.maxed?'<p class="upgrade-complete">✓ Este edificio está al máximo de su era.</p>':`<div class="upgrade-price"><span class="badge">${q.refit?'NUEVO PLANO TECNOLÓGICO':'CONSTRUCTOR + MATERIALES'}</span><h3>${q.refit?'Adaptación a la era actual':'Mejorar al nivel '+q.next}</h3>${cost(s,q.cost)}${materialLedger(s,q.cost)}<p>${time(q.duration)} de trabajo · ${G.STOCK_NAMES[q.mineral]} ${s.knowledge[q.mineral]?'estudiado ✓':'sin estudiar'}</p><button class="primary full" data-action="upgrade-confirm" data-id="${id}" ${!s.knowledge[q.mineral]||!G.canAfford(m,q.cost)?'disabled':''}>${!s.knowledge[q.mineral]?'Estudia primero el material':!G.canAfford(m,q.cost)?'Faltan materiales entregados':'Iniciar mejora'}</button></div>`}<p class="tiny">El edificio presta servicio durante la mejora. La obra se detiene si el constructor se retira. Las adaptaciones de era empiezan en nivel 1 con un plano más avanzado.</p>`;}
export function cityPanel(s){const m=G.currentMap(s),c=m.city,workers=m.units.filter(u=>u.hp>0&&G.TROOPS[u.type].civilian),pending=s.dilemmas.filter(d=>!d.resolved&&d.map===m.id);return head('GOBIERNO Y VIDA COTIDIANA','El pueblo necesita de ti.','Asigna a cada colono un trabajo. La comida y el agua se consumen por habitante; las reservas, el descanso, la contaminación y tus decisiones determinan la productividad.')+`<div class="city-metrics"><article><small>ALIMENTOS</small><strong>${fmt(m.stock.food)}</strong><span>Consumo ${c.foodRate.toFixed(2)}/min · producción ${c.productionFood.toFixed(1)}/min</span>${bar(100-c.hunger)}<small>${c.hunger>=100?'HAMBRUNA':c.hunger>30?'Faltan provisiones':'Población alimentada'}</small></article><article><small>AGUA POTABLE</small><strong>${fmt(m.stock.water)}</strong><span>Consumo ${c.waterRate.toFixed(2)}/min · producción ${c.productionWater.toFixed(1)}/min</span>${bar(100-c.thirst)}<small>${c.thirst>=100?'DESHIDRATACIÓN':c.thirst>30?'Abastecimiento insuficiente':'Reservas de hidratación estables'}</small></article><article><small>BIENESTAR</small><strong>${Math.round(c.happiness)}%</strong><span>Productividad ×${G.productivity(s,m).toFixed(2)}</span>${bar(c.happiness)}<small>Contaminación ${c.pollution.toFixed(1)}%</small></article><article><small>MORALIDAD · ${G.reputation(s).toUpperCase()}</small><strong>${s.ethics.score>=0?'+':''}${s.ethics.score.toFixed(1)}</strong><span>Los pactos y la convivencia dependen de tus acciones.</span>${bar(s.ethics.score+100,200)}</article></div><p class="callout">Energía de la isla: ${G.energyStatus(s,m).capacity.toFixed(1)} de capacidad / ${G.energyStatus(s,m).demand} de demanda. Las instalaciones industriales requieren capacidad suficiente; mejorar las centrales aumenta el suministro.</p><p class="callout">Al comenzar, el manantial junto al colono permite recoger agua sin edificios. Construye un pozo y asigna operarios para abastecer al pueblo. Las granjas necesitan agua y agricultores.</p>`+
 pending.map(d=>{const v=G.dilemmaSpec(d);return`<article class="dilemma"><span class="badge">DECISIÓN PENDIENTE</span><h3>${v.title}</h3><p>${v.text}</p><div class="decision-options">${v.choices.map(o=>`<div><strong>${o.label}</strong><p>${o.effect}</p>${cost(s,o.cost)}<button data-action="decision" data-id="${d.id}" data-type="${o.id}">Elegir</button></div>`).join('')}</div></article>`;}).join('')+
 `<h3>Políticas del imperio</h3><div class="policy-grid">${[['rations','Alimentación',[['normal','Ración normal','Consumo equilibrado'],['generous','Ración generosa','+25% comida · +10 bienestar'],['strict','Racionamiento','−35% comida · −15 bienestar']]],['labor','Trabajo',[['balanced','Jornada equilibrada','Producción estable'],['rest','Descanso protegido','−10% trabajo · +10 bienestar'],['forced','Trabajo forzado','+20% trabajo · −20 bienestar · pierde moralidad']]],['nature','Entorno',[['balanced','Uso responsable','Extracción normal'],['protect','Conservación','Reduce contaminación · reputación gradual'],['extract','Explotación intensiva','+15% recolección · pérdida por tala']]]].map(([key,label,options])=>`<article class="card"><h3>${label}</h3>${options.map(([value,name,effect])=>`<button class="policy-option ${s.ethics.policies[key]===value?'active':''}" data-action="policy" data-id="${key}" data-type="${value}"><strong>${name}</strong><small>${effect}</small></button>`).join('')}</article>`).join('')}</div><h3 style="margin-top:25px">Oficios de los colonos</h3><div class="toolbar"><select id="selected-work" aria-label="Trabajo para colonos seleccionados">${Object.entries(taskNames).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select><button data-action="assign-selected">Asignar a seleccionados</button><small>Para granjas y pozos, usa el botón de su edificio. Mineros: desciende primero a una galería.</small></div><div class="worker-list">${workers.map(u=>`<div class="worker-row"><span><b>${G.SPECIES[u.species].symbol} ${G.SPECIES[u.species].name} · ${u.id}</b><small>${u.assignment?taskNames[u.assignment.task]:'Control manual'} · ${u.order.kind==='hold'?'en espera':u.order.kind==='gather'?'recolectando':u.order.kind==='operate'?'operando edificio':u.order.kind==='infrastructure'?'construyendo camino':u.order.kind==='study'?'investigando':'trabajando'} · capa ${u.depth}</small></span><button data-action="focus-worker" data-id="${u.id}">Localizar</button><button data-action="worker-task" data-id="${u.id}" data-type="wood">Madera</button><button data-action="worker-task" data-id="${u.id}" data-type="food">Comida</button><button data-action="worker-task" data-id="${u.id}" data-type="water">Agua</button><button data-action="worker-task" data-id="${u.id}" data-type="idle">Liberar</button></div>`).join('')}</div><h3 style="margin-top:25px">Edificios y mejoras</h3><div class="cards">${m.buildings.filter(b=>b.hp>0).map(b=>`<article class="card">${art(b.type,false,b.tier,b.level)}<span class="badge">NIVEL ${b.level} / 10 · ${esc(G.ERAS[b.tier||0].name)}</span><h3>${G.STRUCTURES[b.type].name}</h3><p>${G.STRUCTURES[b.type].description}</p><button data-action="inspect-upgrade" data-id="${b.id}">Información y mejoras</button>${G.STRUCTURES[b.type].expansion||G.DEFENSES[b.type]?buildingDetails(s,b):''}${['farm','greenhouse','well','waterworks'].includes(b.type)?`<button data-action="staff-building" data-id="${b.id}" data-type="${['farm','greenhouse'].includes(b.type)?'farm':'well'}">Asignar un operario libre</button>`:''}</article>`).join('')||'<div class="empty">Construye el primer campamento y un pozo de agua para fundar la población.</div>'}</div><h3 style="margin-top:25px">Registro de decisiones</h3>${s.ethics.history.slice(0,10).map(v=>`<div class="side-line"><span>${esc(v.reason)}</span><strong>${v.delta>=0?'+':''}${v.delta.toFixed(1)}</strong></div>`).join('')||'<p>Las ayudas, la guerra, los pactos y el trato a los pueblos dejarán su huella aquí.</p>'}`;}
export function sciencePanel(s){const m=G.currentMap(s);return head('MINERALOGÍA Y APLICACIONES','Primero conocer. Después transformar.','Excava muestras de la geología real de cada isla. El primer estudio revela y habilita usos; el segundo mejora la extracción; el tercero reduce un 10% los costes de las mejoras que usan ese mineral.')+'<div class="cards">'+Object.entries(G.MINERALS).map(([key,v])=>{const level=s.knowledge[key]||0,job=m.civicJobs.find(j=>j.material===key),samples=[5,12,24][level];return`<article class="card mineral-card"><span class="mineral-symbol mineral-${key}">⬡</span><span class="badge">ESTUDIO ${level} / 3 · CAPA ${v.depth}+</span><h3>${G.STOCK_NAMES[key]}</h3><p>${fmt(m.stock[key])} muestras en esta isla<br>${level?v.use:'Usos desconocidos. Analiza muestras antes de emplearlas en mejoras.'}</p>${job?bar(job.elapsed,job.duration)+`<p>En estudio · ${time(job.duration-job.elapsed)} de trabajo</p><button data-action="resume-civic" data-id="${job.id}">Asignar investigador</button>`:level<3?cost(s,{[key]:samples,wood:20+level*20,food:5+level*5})+`<button class="primary" data-action="study" data-type="${key}" ${s.era<v.era?'disabled':''}>${s.era<v.era?'Requiere '+G.ERAS[v.era].name:'Estudiar muestras · fase '+(level+1)}</button>`:'<span class="badge">APLICACIONES DOMINADAS</span>'}</article>`;}).join('')+'</div><p class="callout">Los minerales raros aparecen como muestras adicionales al excavar; la geología principal y las galerías de las partidas anteriores permanecen. Para petróleo necesitas refinería y tuberías, y para análisis avanzados, una casa de estudios.</p>';}
export function progressionPanel(s){const m=G.currentMap(s),complete=G.eraQuote(s,'complete'),rush=G.eraQuote(s,'rush'),next=G.ERAS[s.era+1];return head(G.ERAS.length+' ERAS · 10 NIVELES POR ERA','De un colono a un imperio.','La capital marca los diez niveles de cada era. Puedes desarrollar toda tu civilización para obtener el descuento de avance o gastar una enorme reserva para adelantar la siguiente era.')+`<section class="progression-hero"><div><span class="badge">ERA ${s.era+1} / ${G.ERAS.length}</span><h2>${G.ERAS[s.era].name}</h2><p>Nivel ${s.ageLevel} / 10 · ${G.ERAS[s.era].domain}</p><div class="level-pips">${Array.from({length:10},(_,i)=>`<i class="${i<s.ageLevel?'filled':''}">${i+1}</i>`).join('')}</div></div><p>${G.ERAS[s.era].bonus}<br>Excavación hasta la capa ${G.ERAS[s.era].depth}. Mejora un campamento para aumentar el nivel de la capital.</p></section>`+(s.research?`<article class="card"><h3>Investigando ${G.ERAS[s.research.era].name}</h3>${bar(s.research.elapsed,s.research.duration)}<p>${time(s.research.duration-s.research.elapsed)} de tiempo jugado restante.</p></article>`:next?`<div class="advancement-options"><article class="card"><span class="badge">DESARROLLO COMPLETO · −50% COSTE BASE</span><h3>Consolidar ${next.name}</h3><p>Capital de nivel 10, todos los edificios disponibles al máximo de esta era, mineral estudiado y obras terminadas.</p>${cost(s,complete.cost)}<p>${time(complete.duration)} de investigación</p><button class="primary" data-action="research" data-type="complete" ${!complete.eligible?'disabled':''}>${complete.eligible?'Avanzar con descuento':'Completa el desarrollo'}</button></article><article class="card rush-option"><span class="badge">AVANCE ANTICIPADO · COSTE BASE ×12</span><h3>Adelantar la siguiente era</h3><p>Permite avanzar sin maximizar los edificios. Requiere estudiar ${G.STOCK_NAMES[next.mineral]} y reúne un coste 24 veces mayor que la ruta completa.</p>${cost(s,rush.cost)}<p>${time(rush.duration)} de investigación · el doble de tiempo</p><button data-action="research" data-type="rush">Financiar avance anticipado</button></article></div>`:'<p class="upgrade-complete">Has llegado al final del catálogo actual. La estructura permite añadir más eras.</p>')+`<details class="development-checklist"><summary>Desarrollo pendiente de esta era</summary><div class="inventory"><div><small>CAPITAL</small><strong>${s.ageLevel} / 10</strong></div><div><small>EDIFICIOS COMPLETOS</small><strong>${complete.development.required.filter(v=>v.done).length} / ${complete.development.required.length}</strong></div><div><small>MINERAL APLICADO</small><strong>${complete.development.studied?'✓':'Por estudiar'}</strong></div></div>${complete.development.required.map(r=>`<div class="side-line"><span>${r.done?'✓':'○'} ${r.name}</span><strong>${r.count?r.done?'Máximo de era':'Mejoras pendientes':'Sin construir'}</strong></div>`).join('')}</details><div class="era-list">`+G.ERAS.map((e,i)=>`<article class="era-card ${i===s.era?'current':''}"><span class="era-number">${String(i+1).padStart(2,'0')}</span><span class="badge">${e.domain.toUpperCase()}</span><h3>${e.name}</h3><p>10 niveles · ${e.bonus}<br>Profundidad ${e.depth} · mineral: ${G.STOCK_NAMES[e.mineral]}<br>${Object.values(G.STRUCTURES).filter(v=>v.era===i).map(v=>v.name).concat(Object.values(G.TROOPS).filter(v=>v.era===i).map(v=>v.name)).join(' · ')||'Nuevos planos y capacidad de mejora para toda la ciudad.'}</p><span class="badge">${i===s.era?'ERA ACTUAL':i<s.era?'ERA SUPERADA':'POR DESARROLLAR'}</span></article>`).join('')+'</div>';}
export function speciesPanel(s){return head('CONTACTOS REMOTOS Y MISIONES','Otros pueblos, otras posibilidades.','Empiezas con humanos. Algunos pueblos aparecen raramente al explorar; también puedes conseguir un contacto completando una misión exigente. El pacto desbloquea su reclutamiento y sus capacidades.')+'<div class="cards">'+Object.entries(G.SPECIES).map(([id,v])=>{const unlocked=s.species.includes(id),requirements=id==='human'?[]:G.speciesRequirements(s,id);return`<article class="card species-card"><span class="species-symbol">${v.symbol}</span><span class="badge">${unlocked?'PACTO ACTIVO':'PUEBLO REMOTO'}</span><h3>${v.name}</h3><p>${v.description}</p>${requirements.map(r=>`<div class="mission-condition ${r.done?'done':''}">${r.done?'✓':'○'} ${r.text}</div>`).join('')}${unlocked?'<p class="upgrade-complete">Disponible en el selector de pueblo del ejército.</p>':cost(s,v.cost)+`<button class="primary" data-action="unlock-species" data-type="${id}" ${requirements.every(r=>r.done)?'':'disabled'}>Completar misión de contacto</button>`}</article>`;}).join('')+'</div>';}
